basic.code:
-- Low ratings go away
DELETE FROM reviews WHERE rating < 3;

-- A cancelled order: first its lines, then the order
DELETE FROM order_items WHERE order_id = 5;
DELETE FROM orders WHERE id = 5;

-- What is left
SELECT status, COUNT(*) AS orders, SUM(total) AS total
FROM orders
GROUP BY status
ORDER BY status;

CREATE TABLE suppliers (
  id INT AUTO_INCREMENT PRIMARY KEY,
  name VARCHAR(60) NOT NULL,
  email VARCHAR(80) UNIQUE,
  country CHAR(2) NOT NULL DEFAULT 'ES',
  kind ENUM('farm', 'factory', 'wholesale') NOT NULL,
  since DATE
);

INSERT INTO suppliers (name, email, kind, since) VALUES
  ('Huerta Sol', 'sol@example.com', 'farm', '2022-05-01'),
  ('Molinos Sur', 'molinos@example.com', 'factory', '2021-11-15');
INSERT INTO suppliers (name, country, kind)
  VALUES ('Dairy Co', 'FR', 'wholesale');

-- The columns of the new table
SHOW COLUMNS FROM suppliers;

SELECT * FROM suppliers ORDER BY id;

advanced.code:
-- Without an index, MySQL reads the whole table
EXPLAIN SELECT name FROM customers WHERE city = 'Madrid';

CREATE INDEX idx_customers_city ON customers (city);
-- A composite index: status first, then date
CREATE INDEX idx_orders_status_date ON orders (status, ordered);

-- Now it can jump straight to the rows
EXPLAIN SELECT name FROM customers WHERE city = 'Madrid';

-- The indexes of a table (PRIMARY, UNIQUE and the new one)
SELECT table_name AS `table`, index_name AS `index`,
       seq_in_index AS seq, column_name AS `column`, non_unique AS dup
FROM information_schema.statistics
WHERE table_schema = DATABASE() AND table_name IN ('customers', 'orders')
ORDER BY table_name, index_name, seq_in_index;

-- Move 5 units of Croissant into a new order, all or nothing
START TRANSACTION;
INSERT INTO orders (id, customer_id, ordered, status, total)
  VALUES (11, 8, '2024-06-10', 'new', 7.50);
INSERT INTO order_items (order_id, product_id, qty, price)
  VALUES (11, 2, 5, 1.50);
UPDATE products SET stock = stock - 5 WHERE id = 2;
-- Inside the transaction we see our own changes
SELECT stock FROM products WHERE id = 2;
-- Changed our mind: undo everything since START TRANSACTION
ROLLBACK;

SELECT stock, (SELECT COUNT(*) FROM orders) AS orders
FROM products WHERE id = 2;

-- This time for real
START TRANSACTION;
UPDATE products SET stock = stock - 5 WHERE id = 2;
UPDATE products SET stock = stock + 5 WHERE id = 1;
COMMIT;

SELECT id, name, stock FROM products WHERE id IN (1, 2) ORDER BY id;

-- One row per product: the PRIMARY KEY is product_id
CREATE TABLE stock_count (
  product_id INT PRIMARY KEY,
  counted INT NOT NULL,
  times INT NOT NULL DEFAULT 1
);

INSERT INTO stock_count (product_id, counted) VALUES (1, 40), (2, 25);

-- 2 already exists: update it; 3 does not: insert it
INSERT INTO stock_count (product_id, counted) VALUES (2, 23), (3, 12)
AS new
ON DUPLICATE KEY UPDATE counted = new.counted, times = times + 1;

-- INSERT IGNORE skips the duplicate key without an error
INSERT IGNORE INTO stock_count (product_id, counted) VALUES (1, 0);

-- REPLACE deletes the old row and inserts the new one
REPLACE INTO stock_count (product_id, counted) VALUES (3, 11);

SELECT s.product_id, p.name, s.counted, s.times
FROM stock_count s
JOIN products p ON p.id = s.product_id
ORDER BY s.product_id;

DELIMITER //
CREATE PROCEDURE customer_stats(
  IN  p_city   VARCHAR(60),
  OUT p_orders INT,
  OUT p_total  DECIMAL(10,2)
)
BEGIN
  SELECT COUNT(*), COALESCE(SUM(o.total), 0)
    INTO p_orders, p_total
  FROM orders o
  JOIN customers c ON c.id = o.customer_id
  WHERE c.city = p_city AND o.status <> 'cancelled';
END //
DELIMITER ;

-- The results come back in session variables (@...)
CALL customer_stats('Madrid', @madrid_orders, @madrid_total);
CALL customer_stats('London', @london_orders, @london_total);

SELECT @madrid_orders AS madrid_orders, @madrid_total AS madrid_total,
       @london_orders AS london_orders, @london_total AS london_total;

-- Every price change leaves a line in this log
CREATE TABLE price_log (
  id INT AUTO_INCREMENT PRIMARY KEY,
  product_id INT,
  old_price DECIMAL(8,2),
  new_price DECIMAL(8,2)
);

DELIMITER //
CREATE TRIGGER products_price_log
AFTER UPDATE ON products
FOR EACH ROW
BEGIN
  IF NEW.price <> OLD.price THEN
    INSERT INTO price_log (product_id, old_price, new_price)
    VALUES (OLD.id, OLD.price, NEW.price);
  END IF;
END //
DELIMITER ;

UPDATE products SET price = price + 0.20 WHERE category_id = 1;
UPDATE products SET stock = stock + 1 WHERE category_id = 1;  -- no log
UPDATE products SET price = 9.50 WHERE id = 4;

SELECT l.id, p.name, l.old_price, l.new_price
FROM price_log l
JOIN products p ON p.id = l.product_id
ORDER BY l.id;

-- CHECK constraints are enforced since MySQL 8.0.16
ALTER TABLE products
  ADD CONSTRAINT price_positive CHECK (price > 0),
  ADD CONSTRAINT stock_not_negative CHECK (stock >= 0);

ALTER TABLE reviews
  ADD CONSTRAINT rating_1_to_5 CHECK (rating BETWEEN 1 AND 5);

-- A valid row goes in
INSERT INTO reviews (product_id, rating, comment) VALUES (5, 4, 'Smooth');

SELECT constraint_name AS name, check_clause AS rule
FROM information_schema.check_constraints
WHERE constraint_schema = DATABASE()
ORDER BY constraint_name;

-- This one breaks a CHECK: MySQL refuses it
INSERT INTO reviews (product_id, rating, comment) VALUES (5, 9, 'Amazing');
